import json, urllib.request, urllib.error

TOKEN = open('/tmp/owner_token.txt').read().strip()
BASE = 'https://api.ivxholding.com'

def api_call(path, body=None, method='POST', timeout=30):
    h = {'Content-Type': 'application/json', 'Authorization': f'Bearer {TOKEN}'}
    d = json.dumps(body).encode() if body else None
    req = urllib.request.Request(f'{BASE}{path}', data=d, headers=h, method=method)
    try:
        with urllib.request.urlopen(req, timeout=timeout) as r:
            raw = r.read()
            return r.status, json.loads(raw) if raw else {}
    except urllib.error.HTTPError as e:
        raw = e.read()
        try:
            return e.code, json.loads(raw) if raw else {}
        except:
            return e.code, {'raw': raw.decode('utf-8', errors='replace')[:500]}
    except Exception as e:
        return 0, {'error': str(e)}

# Step 1: Query current deals
print('=== STEP 1: Query current deals ===')
s, d = api_call('/api/ivx/developer-deploy/action', {
    'action': 'supabase_execute_sql_management',
    'sql': 'SELECT deal_id, title, sale_price, estimated_value, capital_required FROM jv_deals ORDER BY display_order;',
    'confirm': True,
    'confirmText': 'CONFIRM_IVX_SUPABASE_MIGRATION'
})
print(f'HTTP {s}')
if d.get('ok'):
    rows = d.get('result', d.get('rows', d.get('data', [])))
    for row in rows:
        print(f'  {row.get("deal_id")}: {row.get("title")} — sale_price={row.get("sale_price")}, est_value={row.get("estimated_value")}, cap_req={row.get("capital_required")}')
else:
    print(json.dumps(d, indent=2)[:500])

# Step 2: Query current Casa Rosario videos
print('\n=== STEP 2: Query Casa Rosario videos ===')
s2, d2 = api_call('/api/ivx/developer-deploy/action', {
    'action': 'supabase_execute_sql_management',
    'sql': "SELECT id, project_id, title, video_url, is_pinned, is_approved FROM project_videos WHERE title ILIKE '%rosario%' OR project_id ILIKE '%rosario%' ORDER BY created_at;",
    'confirm': True,
    'confirmText': 'CONFIRM_IVX_SUPABASE_MIGRATION'
})
print(f'HTTP {s2}')
if d2.get('ok'):
    rows2 = d2.get('result', d2.get('rows', d2.get('data', [])))
    for row in rows2:
        print(f'  id={row.get("id")}, project_id={row.get("project_id")}, title={row.get("title")}, url={row.get("video_url")}, pinned={row.get("is_pinned")}, approved={row.get("is_approved")}')
else:
    print(json.dumps(d2, indent=2)[:500])

# Step 3: Query all project_videos to see what exists
print('\n=== STEP 3: Query ALL project_videos ===')
s3, d3 = api_call('/api/ivx/developer-deploy/action', {
    'action': 'supabase_execute_sql_management',
    'sql': 'SELECT id, project_id, title, video_url, is_pinned, is_approved FROM project_videos ORDER BY created_at LIMIT 20;',
