s, ref = api_call(f"{API}/{OWNER}/{REPO}/git/refs/heads/{BRANCH}", 'PATCH', {
    'sha': commit['sha'],
    'force': False
})
print(f"SUCCESS: pushed {commit['sha'][:12]} to {BRANCH}")
