        except: return e.code, {'raw': raw.decode('utf-8', errors='replace')[:1000]}
    except Exception as e:
        return 0, {'error': str(e)}

def execute_sql(sql):
    s, d = api_call('/api/ivx/developer-deploy/action', {
        'action': 'supabase_execute_sql_management',
        'input': {'sql': sql},
        'confirm': True,
        'confirmText': 'CONFIRM_IVX_SUPABASE_MIGRATION'
    })
    if d.get('ok') and isinstance(d.get('result'), dict):
        result = d['result']
        if result.get('ok'):
            return result.get('rows', [])
        else:
            err = result.get("error", "")
            print(f'  SQL ERROR: {err[:400]}')
            return None
    elif not d.get('ok'):
        print(f'  API ERROR: {d.get("error", "")[:300]}')
        return None
    return []

# The video is now on S3 at: https://ivxholding.com.s3.us-east-1.amazonaws.com/reels/casa-rosario-drone-20260722/casa-rosario-drone-2026-07-22.mp4
