VALUES (
  'casa-rosario-001',
  'Casa Rosario — Drone Tour 2026-07-22',
  '{VIDEO_URL}',
  true,
  true,
  'video/mp4',
  15768485,
  'landscape',
  0
)
RETURNING id, title, video_url, is_pinned, is_approved;
""")
if rows is not None:
    print(f'  Inserted: {len(rows)} row(s)')
    for row in rows:
        print(f'  id={row.get("id")}')
        print(f'  title={row.get("title")}')
        print(f'  url={row.get("video_url")}')
        print(f'  pinned={row.get("is_pinned")}, approved={row.get("is_approved")}')

# Step 2: Verify all Casa Rosario videos in DB
print('\n=== STEP 2: Verify Casa Rosario videos in DB ===')
rows2 = execute_sql("SELECT id, title, video_url, is_pinned, is_approved FROM project_videos WHERE title ILIKE '%rosario%' ORDER BY created_at;")
if rows2 is not None:
    print(f'  Found {len(rows2)} Casa Rosario video(s)')
    for row in rows2:
        print(f'  id={row.get("id")}, title={row.get("title")}, pinned={row.get("is_pinned")}, approved={row.get("is_approved")}')
        print(f'    url={row.get("video_url")}')

